// CORS-friendly API caller
const originalCallApi = async (data: any) => {
  try {
    const url = data && data.action ? `${GOOGLE_SCRIPT_URL}?action=${encodeURIComponent(data.action)}` : GOOGLE_SCRIPT_URL;
    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify(data)
    });
    return await response.json();
  } catch (e) {
    console.error("API Call error:", e);
    return { success: false, message: "Network connection failed." };
  }
};

const callApi = async (data: any) => {
  return await callSupabase(data, originalCallApi);
};

// CORS-friendly Traffic API caller
const callTrafficApi = async (data: any) => {
  try {
    const url = data && data.action ? `${TRAFFIC_SCRIPT_URL}?action=${encodeURIComponent(data.action)}` : TRAFFIC_SCRIPT_URL;
    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify(data)
    });
    return await response.json();
  } catch (e) {
    console.error("Traffic API Call error:", e);
    return { success: false, message: "Traffic Network connection failed." };
  }
};

