  const cleanDateTime = (val: any): string => {
    if (!val) return '-';
    let str = String(val).trim();
    if (!str || str === '-') return '-';

    // If it contains "1899", it is a Google Sheets reference date for time. Extract the time part.
    if (str.includes('1899')) {
      const timeMatch = str.match(/(\d{2}:\d{2}:\d{2})/);
      if (timeMatch) {
        const parts = timeMatch[1].split(':');
        const hh = parseInt(parts[0], 10);
        const mm = parts[1];
        const ampm = hh >= 12 ? 'PM' : 'AM';
        const displayHh = hh % 12 || 12;
        return `${displayHh}:${mm} ${ampm}`;
      }
      const tokens = str.split(/\s+/);
      for (const token of tokens) {
        if (token.includes(':')) {
          return token.split(':').slice(0, 2).join(':');
        }
      }
    }

    // If it is a full GMT date string, e.g. "Sun Jul 19 2026 00:00:00 GMT..."
    if (str.includes('GMT') || str.includes('GM') || str.includes('India Standard Time')) {
      const parsed = Date.parse(str);
      if (!isNaN(parsed)) {
        const d = new Date(parsed);
        const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
        if (d.getHours() !== 0 || d.getMinutes() !== 0 || d.getSeconds() !== 0) {
          const hh = d.getHours();
          const mm = String(d.getMinutes()).padStart(2, '0');
          const ampm = hh >= 12 ? 'PM' : 'AM';
          const displayHh = hh % 12 || 12;
          return `${dateStr} ${displayHh}:${mm} ${ampm}`;
        }
        return dateStr;
      }
    }

    // If it's an ISO date string, e.g., 2026-07-19T18:27:17
    if (str.includes('T')) {
      const parts = str.split('T');
      const dateParts = parts[0].split('-');
      if (dateParts.length === 3) {
        const timePart = parts[1] ? parts[1].split('.')[0] : '';
        const cleanDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
        if (cleanDate.includes('1899')) {
          if (timePart) {
            const tParts = timePart.split(':');
            const hh = parseInt(tParts[0], 10);
            const mm = tParts[1];
            const ampm = hh >= 12 ? 'PM' : 'AM';
            const displayHh = hh % 12 || 12;
            return `${displayHh}:${mm} ${ampm}`;
          }
        }
        if (timePart) {
          const tParts = timePart.split(':');
          const hh = parseInt(tParts[0], 10);
          const mm = tParts[1];
          const ampm = hh >= 12 ? 'PM' : 'AM';
          const displayHh = hh % 12 || 12;
          return `${cleanDate} ${displayHh}:${mm} ${ampm}`;
        }
        return cleanDate;
      }
    }

    if (/^\d{2}:\d{2}:\d{2}$/.test(str) || /^\d{2}:\d{2}$/.test(str)) {
      const parts = str.split(':');
      const hh = parseInt(parts[0], 10);
      const mm = parts[1];
      const ampm = hh >= 12 ? 'PM' : 'AM';
      const displayHh = hh % 12 || 12;
      return `${displayHh}:${mm} ${ampm}`;
    }

    return str;
  };

  const formatCardExpiry = (expiry: any): string => {
    if (!expiry) return 'N/A';
    const str = String(expiry).trim();
    if (/^\d{2}\/\d{2}$/.test(str)) return str;
    if (/^\d{2}\/\d{4}$/.test(str)) {
      const parts = str.split('/');
      return `${parts[0]}/${parts[1].slice(-2)}`;
    }
    const parsed = Date.parse(str);
    if (!isNaN(parsed)) {
      const d = new Date(parsed);
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const y = String(d.getFullYear()).slice(-2);
      return `${m}/${y}`;
    }
    return str;
  };

  const formatCardCvv = (cvv: any): string => {
    if (!cvv) return 'N/A';
    const str = String(cvv).trim();
    if (/^\d{3,4}$/.test(str)) return str;
    if (str.includes('GMT') || str.includes('Sun') || str.includes('Mon') || str.includes('Tue') || str.includes('Wed') || str.includes('Thu') || str.includes('Fri') || str.includes('Sat')) {
      return '***';
    }
    return str.slice(0, 4);
  };

