    if (!cheque || typeof cheque !== 'object') return null;

    const safeEmail = String(cheque.email || userEmail || selectedEntryUser || 'user@crwo.org');
    const rawDate = String(cheque.date || '22122025').replace(/[^0-9]/g, '');
    const dateChars = rawDate.padEnd(8, '0').slice(0, 8).split('');

    const statusStr = String(cheque.statusNotes || '');
    let highlightText = '';
    let statusBefore = statusStr;
    let statusAfter = '';

    const netMatch = statusStr.match(/(N-?[\d,]+(?:\s*INR)?)/i);
    if (netMatch) {
      const idx = statusStr.indexOf(netMatch[0]);
      statusBefore = statusStr.slice(0, idx);
      highlightText = netMatch[0];
      statusAfter = statusStr.slice(idx + netMatch[0].length);
    }

